/** W3C Trace Context, generated by the Site, never accepted from a browser. */
export function createHomelabTrace(): { traceId: string; traceparent: string } {
  const traceId = crypto.randomUUID().replace(/-/g, "");
  const spanId = crypto.randomUUID().replace(/-/g, "").slice(0, 16);
  return { traceId, traceparent: `00-${traceId}-${spanId}-01` };
}

/** Bound outbound trace headers and reject invalid all-zero IDs and injection. */
export function validHomelabTraceparent(value: unknown): value is string {
  if (typeof value !== "string") return false;
  const match = /^00-([a-f0-9]{32})-([a-f0-9]{16})-(00|01)$/.exec(value);
  return Boolean(match && !/^0+$/.test(match[1]) && !/^0+$/.test(match[2]));
}
